import{_ as n,c as i,a as s,o as t}from"./app-Dwqo-Lyc.js";const l="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-1-BM7iYMkm.png",r="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-2-D78LFMbB.png",o="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-3-DSjGC6hb.png",p="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-4-CXJJEud1.png",c="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-5-MAXg1psT.png",d="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-6-Cch8b7du.png",u="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-7-Dsu-zDD3.png",h="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-8-DHOdv9hn.png",g="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-9-m1aXztP5.png",m="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-10-D69vcyko.png",v="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-32-BlQCipCs.png",f="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-33-CYhLq8an.png",b="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-34-COXtQjaH.png",k="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-11-05FFyAC8.png",w="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-12-BD5EaoZ9.png",C="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-13-L8F32yMY.png",y="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-16-BH4LDnBV.png",M="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-17-DI9NBKvy.png",V="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-14-DvbY5T4s.png",e="data:image/png;base64,",I="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-26-BBzb-wE3.png",A="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-35-BMx3Sjao.png",S="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-36-BFPsLvp7.png",x="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-37-DjqGpW4Z.png",T="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-38-CzNHbUbj.png",D="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-39-BLE0MNpS.png",N="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-40-CUVJsVKj.png",P="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-41-il_32xKE.png",_="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-42-D3MkMZGY.png",O="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-43-CgPHb189.png",L="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-44-DeuEG2aZ.png",q="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt27-CaUBDVbM.png",z="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt28-DeefmyWS.png",E="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt29-CZbvLljm.png",U="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt30-BgL0vJY0.png",R="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt31-CImxxFkC.png",F="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-18-Bb90rMOO.png",G="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-19-CceIDhRn.png",j="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-21-COUfJU_J.png",B="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-22-CimSAmVL.png",H="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-45-aGb0QhFh.png",Y="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-46-C97ItukK.png",K="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-47-Drnv76b9.png",J="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-48-CboJvHVT.png",W="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-49-DgSUqWA6.png",Q="/hpe-solutions-openshift/4.21-AMD-LTI/assets/figure-virt-50-WiYrQ5jw.png",Z={};function X($,a){return t(),i("div",null,a[0]||(a[0]=[s('<h1 id="openshift-virtualization" tabindex="-1"><a class="header-anchor" href="#openshift-virtualization"><span><strong>OpenShift Virtualization</strong></span></a></h1><h2 id="install-and-configure-openshift-virtulization" tabindex="-1"><a class="header-anchor" href="#install-and-configure-openshift-virtulization"><span><strong>Install and Configure Openshift Virtulization</strong></span></a></h2><h4 id="introduction" tabindex="-1"><a class="header-anchor" href="#introduction"><span>Introduction</span></a></h4><p>RedHat OpenShift Virtualization stands as a cornerstone of Red Hat&#39;s OpenShift Container Platform, seamlessly blending virtual machines and containers to offer a unified management interface. This integration empowers organizations to efficiently deploy both modern and traditional applications, encompassing virtual machines, containers, and serverless functions within a single platform. Built upon the &quot;container-native virtualization&quot; concept, driven by the KubeVirt project, it harnesses the RHEL KVM hypervisor to seamlessly merge virtual machines with Kubernetes and KubeVirt for streamlined management and orchestration. Through this infrastructure, OpenShift Virtualization enables the coexistence of virtual machines and containers within a Kubernetes environment, providing a cohesive solution for workload management.</p><p>OpenShift Virtualization adds new objects into your OpenShift Container Platform cluster via Kubernetes custom resources to enable virtualization tasks. These tasks include:</p><ul><li><p>Creating and managing Linux and Windows virtual machines</p></li><li><p>Connecting to virtual machines through a variety of consoles and CLI tools</p></li><li><p>Importing and cloning existing virtual machines</p></li><li><p>Managing network interface controllers and storage disks attached to virtual machines</p></li><li><p>Live migrating virtual machines between nodes</p></li><li><p>An enhanced web console provides a graphical portal to manage these virtualized resources alongside the OpenShift Container Platform cluster containers and infrastructure.</p></li><li><p>OpenShift Virtualization is tested with OpenShift Data Foundation (ODF) and Alletra MP Storage.</p></li><li><p>OpenShift Virtualization allows the usage with either the [OVN-Kubernetes] (opens new window)or the [OpenShiftSDN] (opens new window)default Container Network Interface (CNI) network provider</p></li></ul><h4 id="enabling-openshift-virtualization" tabindex="-1"><a class="header-anchor" href="#enabling-openshift-virtualization"><span>Enabling OpenShift Virtualization</span></a></h4><p><img src="'+l+'" alt=""></p><p><strong>FIGURE 26.</strong> Red Hat OpenShift Virtualization deployment flow</p><h4 id="installing-openshift-virtualization-operator-from-operatorhub" tabindex="-1"><a class="header-anchor" href="#installing-openshift-virtualization-operator-from-operatorhub"><span>Installing OpenShift Virtualization Operator from OperatorHub</span></a></h4><ol><li><p>Log into the OpenShift Container Platform web console and navigate to Ecosystem → Software Catalog.</p></li><li><p>Select an existing project name or create new project.</p></li><li><p>Type OpenShift Virtualization and Select OpenShift Virtualization tile</p></li></ol><p><img src="'+r+'" alt=""></p><p><strong>FIGURE 27.</strong> OpenShift Virtualization in Software Catalog</p><ol start="4"><li>Click and Install the Operator to the &quot;openshift-cnv&quot; namespace</li></ol><p><img src="'+o+'" alt=""></p><p><strong>FIGURE 28.</strong> Inputs for the OpenShift Virtualization operator</p><ol start="5"><li>Once OpenShift Virtualization is successfully installed , Create HyperConverged Custom resource</li></ol><p><img src="'+p+'" alt=""></p><p><img src="'+c+'" alt=""></p><p><strong>FIGURE 29.</strong> Creation of HyperConverged in OpenShift Virtualization operator</p><p>After successful deployment of operator and creation of HyderConverged. Virtualization will be enabled in webconsole.</p><h4 id="network-configuration" tabindex="-1"><a class="header-anchor" href="#network-configuration"><span>Network configuration</span></a></h4><p>You would have internal pod network as default network after successful deployment of OpenShift Virtualization. For additional network, we would deploy the network operator &quot;NMState Operator&quot; and configure Linux bridge network for external VM access and live migration.</p><p>Administrators can also install SR-IOV Operator to manage SR-IOV network devices and MetalLB Operator for lifecycle management.</p><h4 id="configuring-a-linux-bridge-network" tabindex="-1"><a class="header-anchor" href="#configuring-a-linux-bridge-network"><span>Configuring a Linux bridge Network</span></a></h4><ol><li><p>To install NMState Operator, navigate to Ecosystem → Software Catalog in webconsole.</p></li><li><p>Select an existing project name or create new project.</p></li><li><p>Type NMState, Select Kubernetes NMState Operator tile and Install the Operator</p></li></ol><p><img src="'+d+'" alt=""></p><p><strong>FIGURE 30.</strong> Installation of NMState in OperatorHub</p><ol start="4"><li>Once the NMState operator is installed, Create a instance for &quot;nmstate&quot;</li></ol><p><img src="'+u+`" alt=""></p><p><strong>FIGURE 31.</strong> Inputs for NMState in operator</p><h4 id="creating-a-linux-bridge-nncp" tabindex="-1"><a class="header-anchor" href="#creating-a-linux-bridge-nncp"><span>Creating a Linux bridge NNCP</span></a></h4><p>Create a NodeNetworkConfigurationPolicy (NNCP) manifest for a Linux bridge network for network interface card(enp1s0) and apply the created NNCP manifest</p><ol><li>Click on Networking &gt; NodeNetworkConfigurationPolicy &gt; Click on create with yaml and add below content.</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: nmstate.io/v1</span>
<span class="line">kind: NodeNetworkConfigurationPolicy</span>
<span class="line">metadata:</span>
<span class="line">  name: br-ex-network</span>
<span class="line">spec:</span>
<span class="line">  nodeSelector:</span>
<span class="line">    node-role.kubernetes.io/worker: <span class="token string">&quot;&quot;</span></span>
<span class="line">  desiredState:</span>
<span class="line">    ovn:</span>
<span class="line">      bridge-mappings:</span>
<span class="line">      - bridge: br-ex</span>
<span class="line">        localnet: br-ex-network</span>
<span class="line">        state: present</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Click on Create.</li></ol><h4 id="creating-a-linux-bridge-nad" tabindex="-1"><a class="header-anchor" href="#creating-a-linux-bridge-nad"><span>Creating a Linux bridge NAD</span></a></h4><p>A NetworkAttachmentDefinition allows VMs to connect to secondary networks using Multus.</p><ol><li><p>Log in to the OpenShift Container Platform web console and click Networking → NetworkAttachmentDefinitions</p></li><li><p>Click Create Network Attachment Definition (NAD). And provide the required details</p></li><li><p>Click the Network Type list and select OVN Kubernetes L2 overlay network</p></li><li><p>Enter the name of the bridge (Previously created NodeNetworkConfigurationPolicy object as interfaces name ex: bridge-ex-network) in the Bridge Name field</p></li><li><p>Click Create</p></li></ol><p><img src="`+h+`" alt=""></p><p><strong>FIGURE 32.</strong> Creation of NAD</p><h4 id="creating-a-dedicated-network-for-live-migration" tabindex="-1"><a class="header-anchor" href="#creating-a-dedicated-network-for-live-migration"><span>Creating a dedicated network for live migration</span></a></h4><ol><li>Administrators have to create additional NAD for creating a dedicated live migration network. Create a NAD manifest as below</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: <span class="token string">&quot;k8s.cni.cncf.io/v1&quot;</span></span>
<span class="line">kind: NetworkAttachmentDefinition</span>
<span class="line">metadata:</span>
<span class="line">  name: migration-network </span>
<span class="line">  namespace: openshift-cnv </span>
<span class="line">spec:</span>
<span class="line">  config: <span class="token string">&#39;{</span>
<span class="line">    &quot;cniVersion&quot;: &quot;0.3.1&quot;,</span>
<span class="line">    &quot;name&quot;: &quot;migration-bridge&quot;,</span>
<span class="line">    &quot;type&quot;: &quot;macvlan&quot;,</span>
<span class="line">    &quot;master&quot;: &quot;enp1s1&quot;, </span>
<span class="line">    &quot;mode&quot;: &quot;bridge&quot;,</span>
<span class="line">    &quot;ipam&quot;: {</span>
<span class="line">      &quot;type&quot;: &quot;whereabouts&quot;, </span>
<span class="line">      &quot;range&quot;: &quot;20.0.0.0/24&quot; </span>
<span class="line">    }</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Goto the custom resource of Hydercoverged that was created during &quot;OpenShift Virtualization&quot; operator deployment and Specify the created network name for &quot;spec.liveMigrationConfig&quot;</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: hco.kubevirt.io/v1beta1</span>
<span class="line">kind: HyperConverged</span>
<span class="line">metadata:</span>
<span class="line">  name: kubevirt-hyperconverged</span>
<span class="line">spec:</span>
<span class="line">  liveMigrationConfig:</span>
<span class="line">    completionTimeoutPerGiB: <span class="token number">800</span></span>
<span class="line">    network: migration-network  <span class="token comment">#specify migration network name</span></span>
<span class="line">    parallelMigrationsPerCluster: <span class="token number">5</span></span>
<span class="line">    parallelOutboundMigrationsPerNode: <span class="token number">2</span></span>
<span class="line">    progressTimeout: <span class="token number">150</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="create-a-virtual-machine" tabindex="-1"><a class="header-anchor" href="#create-a-virtual-machine"><span>Create a virtual machine</span></a></h4><p>The web console features an interactive wizard that guides you through General, Networking, Storage, Advanced, and Review steps to simplify the process of creating virtual machines. All required fields are marked by a *. When the required fields are completed, you can review and create your virtual machine.</p><p>Network Interface Cards (NICs) and storage disks can be created and attached to virtual machines after they have been created.</p><p>Use one of these procedures to create a virtual machine:</p><ul><li><p>Creating virtual machines from templates</p></li><li><p>Creating virtual machines from instance types</p></li><li><p>Creating virtual machines from CLI</p></li></ul><h4 id="creating-virtual-machines-from-templates" tabindex="-1"><a class="header-anchor" href="#creating-virtual-machines-from-templates"><span>Creating virtual machines from templates</span></a></h4><p>You can create virtual machines from templates provided by Red Hat using web console. You can also create customized templates as per requirements.</p><ol><li>Log into the OpenShift Container Platform web console and navigate to Virtualization → Catalog → Template Catalog</li></ol><p><img src="`+g+'" alt=""></p><p><strong>FIGURE 33.</strong> Templates available by default in Virtualization</p><ol start="2"><li>Click the required template to view the details (for example: rhel9)</li></ol><p><img src="'+m+'" alt=""></p><p><strong>FIGURE 34.</strong> Sample deployment of RHEL VM using templates</p><ol start="3"><li>Click &quot;Quick create VirtualMachine&quot; to create a VM from the template. You can customize the CPU/Memory/Storage as required.</li></ol><p>NOTE: If you want to assign Static IP, skip this step and follow the below steps</p><p>To assign a Static IP to VM follow the below steps:</p><ol><li>Click on customize configuration tab &gt; Select Network interfaces &gt; Add Network Interface with NAD created</li></ol><p><img src="'+v+'" alt=""></p><p><strong>FIGURE 35.</strong> Adding Network Interface</p><ol start="2"><li>Click on create for VM creation and check the status of VM by selecting virtual machines &gt; Select default namespace &gt; Click on VM created</li></ol><p><img src="'+f+'" alt=""></p><p><strong>FIGURE 36.</strong> VM created</p><p>IP is assigned as shown below and we can ssh once VM is started after finished initial installation of rhel VM.</p><p><img src="'+b+'" alt=""></p><p><strong>FIGURE 37.</strong> VM with a Static IP</p><h4 id="creating-virtual-machines-from-instance-types" tabindex="-1"><a class="header-anchor" href="#creating-virtual-machines-from-instance-types"><span>Creating virtual machines from instance types</span></a></h4><ol><li>Log into the OpenShift Container Platform web console and navigate to Virtualization → Catalog → Instance Types</li></ol><p><img src="'+k+'" alt=""></p><p><strong>FIGURE 38.</strong> Virtual Machine creation from Catalog</p><ol start="2"><li><p>Select the bootable volumes</p><ul><li>Images provided by RedHat, these images are available in &quot;openshift-virtualization-os-images&quot; namespace.</li><li>Click Add Volume. You can either use any of the existing volume where you have the boot images or you can upload images and create a new volume(PVC) and provide the required parameter.</li></ul><p><img src="'+w+'" alt=""></p><p><strong>FIGURE 39.</strong> Add volumes to import OS images</p></li><li><p>Click the required boot volume.</p></li><li><p>Select the required Instance type</p></li></ol><p><img src="'+C+`" alt=""></p><p><strong>FIGURE 40.</strong> Selection of Instance type and boot image</p><ol start="5"><li>Click &quot;Create VirtualMachine&quot; to create a VM from the instance types.</li></ol><p>You can Customize and create user Instance type as required by navigating to Virtualization → Instance Types → Create.</p><h4 id="creating-virtual-machines-from-cli" tabindex="-1"><a class="header-anchor" href="#creating-virtual-machines-from-cli"><span>Creating virtual machines from CLI</span></a></h4><ol><li>Create a VirtualMachine manifest required for creating a VM</li></ol><p>Below is an example manifest for creating fedora VM</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: kubevirt.io/v1</span>
<span class="line">kind: VirtualMachine</span>
<span class="line">metadata:</span>
<span class="line">  name: my-vm</span>
<span class="line">spec:</span>
<span class="line">  running: <span class="token boolean">false</span></span>
<span class="line">  template:</span>
<span class="line">    metadata:</span>
<span class="line">      labels:</span>
<span class="line">        kubevirt.io/domain: my-vm</span>
<span class="line">    spec:</span>
<span class="line">      domain:</span>
<span class="line">        devices:</span>
<span class="line">          disks:</span>
<span class="line">          - disk:</span>
<span class="line">              bus: virtio</span>
<span class="line">            name: containerdisk</span>
<span class="line">          - disk:</span>
<span class="line">              bus: virtio</span>
<span class="line">            name: cloudinitdisk</span>
<span class="line">        resources:</span>
<span class="line">          requests:</span>
<span class="line">            memory: 8Gi</span>
<span class="line">      volumes:</span>
<span class="line">      - name: containerdisk</span>
<span class="line">        containerDisk:</span>
<span class="line">          image: kubevirt/fedora-cloud-registry-disk-demo</span>
<span class="line">      - name: cloudinitdisk</span>
<span class="line">        cloudInitNoCloud:</span>
<span class="line">          userData: <span class="token operator">|</span></span>
<span class="line">            <span class="token comment">#cloud-config</span></span>
<span class="line">            password: fedora</span>
<span class="line">            chpasswd: <span class="token punctuation">{</span> expire: False <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Apply the created manifest file for virtual machine creation.</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc apply <span class="token parameter variable">-f</span> <span class="token operator">&lt;</span> file-name <span class="token operator">&gt;</span>.yaml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="reading-viewing-virtual-machine" tabindex="-1"><a class="header-anchor" href="#reading-viewing-virtual-machine"><span>Reading/Viewing virtual machine</span></a></h4><p>You can check the virtual machine status, Metrics , resources utilization (CPU, memory, storage) for overall cluster by navigate to Virtualization → Overview.</p><p><img src="`+y+'" alt=""></p><p><strong>FIGURE 41.</strong> Overview Virtual machines in the Cluster</p><p>and access configuration details of VM&#39;s, networks and storage volumes.</p><p><img src="'+M+`" alt=""></p><p><strong>FIGURE 42.</strong> Overview of Sample Virtual machines deployed in the RHOCP platform</p><h4 id="updating-a-virtual-machine" tabindex="-1"><a class="header-anchor" href="#updating-a-virtual-machine"><span>Updating a virtual machine</span></a></h4><p>You can update virtual machine configuration using CLI or from the web console.</p><h4 id="virtual-machine-configuration-using-cli" tabindex="-1"><a class="header-anchor" href="#virtual-machine-configuration-using-cli"><span>Virtual machine configuration using CLI</span></a></h4><ol><li>Virtual machine configuration can be edit/updated</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc edit vm <span class="token operator">&lt;</span> vm-name <span class="token operator">&gt;</span> <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span> namespace <span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>Apply the updated configuration</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc apply vm <span class="token operator">&lt;</span> vm_name <span class="token operator">&gt;</span> <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span> namespace <span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="virtual-machine-configuration-using-web-console" tabindex="-1"><a class="header-anchor" href="#virtual-machine-configuration-using-web-console"><span>Virtual machine configuration using web console</span></a></h4><ol><li><p>Log into the OpenShift Container Platform web console and navigate to Virtualization → VirtualMachines</p></li><li><p>Select the virtual machine For example: addition of the disk navigate to Configuration → Storage → Add disk <img src="`+V+'" alt=""></p><p><strong>FIGURE 43.</strong> Storage disk addition</p></li><li><p>Specify the fields like Source, Size, Storage class as required</p></li><li><p>Click Add</p></li></ol><p>We can add additional networks, secrets, config map to virtual machines.</p><p>Some of the changes are applied once the virtual machine are restarted only. For restarting of any virtual machines navigate to</p><p>Virtualization → VirtualMachines</p><p>Click the Options menu <img src="'+e+`" alt=""> beside a virtual machine name.</p><p>Select Restart or select the virtual machine → Actions → Restart</p><h4 id="deleting-a-virtual-machine" tabindex="-1"><a class="header-anchor" href="#deleting-a-virtual-machine"><span>Deleting a virtual machine</span></a></h4><p>You can delete a virtual machine by using CLI or from the web console.</p><h4 id="delete-a-virtual-machine-using-cli" tabindex="-1"><a class="header-anchor" href="#delete-a-virtual-machine-using-cli"><span>Delete a virtual machine using CLI</span></a></h4><ol><li>Delete the virtual machine by executing the below command:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc delete vm <span class="token operator">&lt;</span> vm_name <span class="token operator">&gt;</span> <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span> namespace <span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="delete-a-virtual-machine-using-web-console" tabindex="-1"><a class="header-anchor" href="#delete-a-virtual-machine-using-web-console"><span>Delete a virtual machine using web console</span></a></h4><ol><li><p>Log into the OpenShift Container Platform web console and navigate to Virtualization → VirtualMachines</p></li><li><p>Click the Options menu <img src="`+e+'" alt=""> beside a virtual machine name and select Delete or Select the virtual machine → Actions → Delete</p></li></ol><p><img src="'+I+`" alt=""></p><p><strong>FIGURE 44.</strong> Deleting a Virtual Machine</p><h2 id="deploying-virtual-machines-on-userdefinednetworks-udn" tabindex="-1"><a class="header-anchor" href="#deploying-virtual-machines-on-userdefinednetworks-udn"><span><strong>Deploying Virtual Machines on UserDefinedNetworks (UDN)</strong></span></a></h2><h4 id="introduction-1" tabindex="-1"><a class="header-anchor" href="#introduction-1"><span>Introduction</span></a></h4><p>UserDefinedNetworks (UDN) provide a way to create isolated network environments for workloads within a namespace. When virtual machines are deployed on a UDN, they receive IP addresses from the defined subnet and operate within that isolated network. This enables better network segmentation, security, and multi-tenant workload separation.</p><h4 id="prerequisites" tabindex="-1"><a class="header-anchor" href="#prerequisites"><span>Prerequisites</span></a></h4><p>OpenShift Virtualization Operator must be installed.</p><h4 id="creating-namespace-with-udn-label" tabindex="-1"><a class="header-anchor" href="#creating-namespace-with-udn-label"><span>Creating Namespace with UDN Label</span></a></h4><ol><li><p>Navigate to Administration → Namespaces.</p></li><li><p>Click Create Namespace.</p></li><li><p>Add the following label while creating the namespace:</p></li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">k8s.ovn.org/primary-user-defined-network<span class="token operator">=</span><span class="token string">&quot;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><img src="`+A+'" alt=""></p><p><strong>FIGURE 45.</strong> Create a new namespace</p><ol start="4"><li>Click Create.</li></ol><p><img src="'+S+'" alt=""></p><p><strong>FIGURE 46.</strong> Namespace created with label</p><h4 id="creating-userdefinednetwork" tabindex="-1"><a class="header-anchor" href="#creating-userdefinednetwork"><span>Creating UserDefinedNetwork</span></a></h4><ol><li><p>Navigate to Networking → User Defined Networks.</p></li><li><p>Click Create.</p></li><li><p>In the Create User Defined Network dialog:</p><ul><li><p>Select the newly created namespace as the Project</p></li><li><p>Provide the Subnet CIDR</p></li></ul></li></ol><p><img src="'+x+'" alt=""></p><p><strong>FIGURE 47.</strong> Creating a UDN for namespace</p><ol start="4"><li>Click Create.</li></ol><p><img src="'+T+'" alt=""></p><p><strong>FIGURE 48.</strong> Created UDN</p><h4 id="creating-virtual-machine-on-udn" tabindex="-1"><a class="header-anchor" href="#creating-virtual-machine-on-udn"><span>Creating Virtual Machine on UDN</span></a></h4><ol><li>Navigate to Virtualization → VirtualMachines.</li></ol><p><img src="'+D+'" alt=""></p><p><strong>FIGURE 49.</strong> VirtualMachines</p><ol start="2"><li><p>Click Create.</p></li><li><p>Select to create a VM from Instance Type or Template.</p></li><li><p>Ensure the Project selected is the namespace where UDN is configured.</p></li></ol><p><img src="'+N+'" alt=""></p><p><strong>FIGURE 50.</strong> Default templates</p><ol start="5"><li>Configure the VM as required and click Create.</li></ol><p><img src="'+P+'" alt=""></p><p><strong>FIGURE 51.</strong> Configuring VM</p><p><img src="'+_+`" alt=""></p><p><strong>FIGURE 52.</strong> VM created</p><h4 id="validation" tabindex="-1"><a class="header-anchor" href="#validation"><span>Validation</span></a></h4><ol><li><p>Once the VM is running, open the VM console.</p></li><li><p>Log in using the credentials displayed on the screen.</p></li><li><p>Check the network configuration:</p></li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token function">ip</span> a</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="4"><li>Verify that the assigned IP address belongs to the configured subnet.</li></ol><p><img src="`+O+`" alt=""></p><p><strong>FIGURE 53.</strong> VM network configuration verification</p><h4 id="network-isolation-check" tabindex="-1"><a class="header-anchor" href="#network-isolation-check"><span>Network Isolation Check</span></a></h4><ol><li>Verify external connectivity:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token function">ping</span> google.com</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The request should fail, confirming network isolation.</p><ol start="2"><li>Verify internal connectivity within subnet:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token function">ping</span> <span class="token operator">&lt;</span>vm-ip-in-same-subnet<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The request should succeed, confirming communication within the UDN.</p><p><img src="`+L+'" alt=""></p><p><strong>FIGURE 54.</strong> Network isolation and internal connectivity validation</p><h2 id="hotplugging" tabindex="-1"><a class="header-anchor" href="#hotplugging"><span><strong>HotPlugging</strong></span></a></h2><h4 id="hot-plugging-vcpus" tabindex="-1"><a class="header-anchor" href="#hot-plugging-vcpus"><span>Hot Plugging vCPUs</span></a></h4><p>Hot plugging means enabling or disabling devices while a virtual machine is running.</p><p>Prerequisites:</p><p>Required minimum 2 worker nodes in cluster</p><p>Steps:</p><ol><li><p>In the Virtualization tab, Navigate to VirtualMachine.</p></li><li><p>Select a running virtual machine that required changes</p></li><li><p>Navigate to Configuration tab and Click Details.</p></li><li><p>Edit the CPU | Memory details</p></li></ol><p><img src="'+q+'" alt=""></p><p><strong>FIGURE 55.</strong> Paramter for hot plugging vCPU- 1</p><ol start="5"><li>Change the value of Virtual Sockets as required.</li></ol><p><img src="'+z+'" alt=""></p><p><strong>FIGURE 56.</strong> Paramter for hot plugging vCPU- 2</p><ol start="6"><li>Click Save.</li></ol><p>Note: Hot Plugging of CPU and Memory is not possible when Virtual machines are created from the Instance type.</p><h4 id="hot-plugging-memory" tabindex="-1"><a class="header-anchor" href="#hot-plugging-memory"><span>Hot Plugging Memory</span></a></h4><p>You can hot plug virtual memory. Each time memory is hot plugged, it appears as a new memory device in the VM Devices tab in the details view of the virtual machine, up to a maximum of 16 available slots. When the virtual machine is restarted, these devices are cleared from the VM Devices tab without reducing the virtual machine’s memory, allowing you to hot plug more memory devices.</p><p>Prerequisites:</p><p>Required minimum 2 worker nodes in cluster</p><p>Steps:</p><ol><li><p>In the Virtualization tab, Navigate to VirtualMachine.</p></li><li><p>Select a running virtual machine that required changes</p></li><li><p>Navigate to Configuration tab and Click Details.</p></li><li><p>Edit the CPU | Memory details</p></li></ol><p><img src="'+E+'" alt=""></p><p><strong>FIGURE 57.</strong> Paramter for hot plugging Memory</p><ol start="5"><li><p>Change the value of Virtual Sockets as required.</p></li><li><p>Click Save.</p></li></ol><p>Note: Hot Plugging of CPU and Memory is not possible when Virtual machines are created from the Instance type.</p><h4 id="hot-plugging-vm-disks" tabindex="-1"><a class="header-anchor" href="#hot-plugging-vm-disks"><span>Hot-plugging VM disks</span></a></h4><p>You can add or remove virtual disks without stopping your virtual machine (VM) or virtual machine instance (VMI). Only data volumes and persistent volume claims (PVCs) can be hot plugged and hot-unplugged. You cannot hot plug or hot-unplug container disks.</p><p>Prerequisites</p><p>You must have a data volume or persistent volume claim (PVC) available for hot plugging.</p><p>Steps:</p><ol><li><p>In the Virtualization tab, Navigate to VirtualMachines</p></li><li><p>Select a running virtual machine that required changes</p></li><li><p>On the VirtualMachine details page, click Configuration Storage</p></li><li><p>Add a hot plugged disk:</p></li></ol><p>i. Click Add disk.</p><p>ii. In the Add disk (hot plugged) window, select the disk from the Source list and click Save.</p><p>Note: Each VM must have Virtio-scsi Controller so that Hot Plug disk can use SCSI bus.</p><p><img src="'+U+'" alt=""></p><p><strong>FIGURE 58.</strong> Paramter for hot plugging VM disks</p><h4 id="hot-plugging-network-interface" tabindex="-1"><a class="header-anchor" href="#hot-plugging-network-interface"><span>Hot-plugging Network Interface</span></a></h4><p>You can add or remove network interfaces without stopping your virtual machine (VM). OpenShift Virtualization supports hot plugging for interfaces that use the VirtIO device driver.</p><p>Prerequisites</p><p>• A network attachment definition is configured in the same namespace as your VM.</p><p>• Required minimum 2 nodes in cluster</p><p>Steps:</p><ol><li><p>In the Virtualization tab, Navigate to VirtualMachines</p></li><li><p>Select a running virtual machine that required changes</p></li><li><p>On the VirtualMachine details page, click Configuration Network Add network interface</p></li></ol><p><img src="'+R+`" alt=""></p><p><strong>FIGURE 59.</strong> Paramter for hot plugging Network Interface</p><ol start="4"><li><p>Add the respective Pod Networking (NAD) that needs to be added to network interface</p></li><li><p>Click Save the network setting.</p></li><li><p>Navigate to Actions  Click Migrate</p></li></ol><p>Once the VM is Successfully migrated to different node. The newly added network interface is available in the virtual machine.</p><h2 id="live-migration" tabindex="-1"><a class="header-anchor" href="#live-migration"><span><strong>Live migration</strong></span></a></h2><h4 id="introduction-2" tabindex="-1"><a class="header-anchor" href="#introduction-2"><span>Introduction</span></a></h4><p>Live migration is the process of moving a running virtual machine (VM) to another node in the cluster without interrupting the virtual workload. By default, live migration traffic is encrypted using Transport Layer Security (TLS).</p><p>An enhanced web console provides a graphical portal to manage these virtualized resources alongside the OpenShift Container Platform cluster containers and infrastructure.</p><h4 id="requirements-of-live-migration" tabindex="-1"><a class="header-anchor" href="#requirements-of-live-migration"><span>Requirements of Live migration</span></a></h4><ul><li><p>A dedicated Multus network for live migration is highly recommended.</p></li><li><p>Persistent Volume Claim (Storage) must have ReadWriteMany (RWX) access mode.</p></li><li><p>All CPU in cluster which hosts Virtual machines must support the host model.</p></li></ul><h4 id="configuring-live-migration" tabindex="-1"><a class="header-anchor" href="#configuring-live-migration"><span>Configuring live migration</span></a></h4><p>You can configure the following live migration settings to ensure the migration process do not saturate the cluster.</p><ul><li><p>Limits and timeouts</p></li><li><p>Maximum number of migrations per node or cluster</p></li></ul><p>Edit the HyperConverged CR and add the necessary live migration parameters:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc edit hyperconverged kubevirt-hyperconverged <span class="token parameter variable">-n</span> openshift-cnv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>sample configuration parameters</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: hco.kubevirt.io/v1beta1</span>
<span class="line">kind: HyperConverged</span>
<span class="line">metadata:</span>
<span class="line">  name: kubevirt-hyperconverged</span>
<span class="line">  namespace: openshift-cnv</span>
<span class="line">spec:</span>
<span class="line">  liveMigrationConfig:</span>
<span class="line">    bandwidthPerMigration: 64Mi </span>
<span class="line">    completionTimeoutPerGiB: <span class="token number">800</span> </span>
<span class="line">    parallelMigrationsPerCluster: <span class="token number">5</span> </span>
<span class="line">    parallelOutboundMigrationsPerNode: <span class="token number">2</span> </span>
<span class="line">    progressTimeout: <span class="token number">150</span> </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="initiating-live-migration" tabindex="-1"><a class="header-anchor" href="#initiating-live-migration"><span>Initiating Live Migration</span></a></h4><p>Live migration of virtual machines can be done using web console or CLI. prerequisites must be met for the live migration of any virtual machines.</p><h4 id="initiating-live-migration-using-web-console" tabindex="-1"><a class="header-anchor" href="#initiating-live-migration-using-web-console"><span>Initiating Live Migration using web console</span></a></h4><ol><li><p>Navigate to Virtualization → VirtualMachines in the web console.</p></li><li><p>Select Migrate from the Options menu <img src="`+e+'" alt=""> beside a VM.</p></li></ol><p><img src="'+F+`" alt=""></p><p><strong>FIGURE 60.</strong> Live Migration between nodes</p><ol start="3"><li>Click Migrate.</li></ol><h4 id="initiating-live-migration-using-cli" tabindex="-1"><a class="header-anchor" href="#initiating-live-migration-using-cli"><span>Initiating Live Migration using CLI</span></a></h4><ol><li>Create and apply the VirtualMachineInstanceMigration manifest for the VM</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">apiVersion: kubevirt.io/v1</span>
<span class="line">kind: VirtualMachineInstanceMigration</span>
<span class="line">metadata:</span>
<span class="line">  name: <span class="token operator">&lt;</span> migration_name <span class="token operator">&gt;</span></span>
<span class="line">spec:</span>
<span class="line">  vmiName: <span class="token operator">&lt;</span> vm_name <span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="migration-toolkit-for-virtualization" tabindex="-1"><a class="header-anchor" href="#migration-toolkit-for-virtualization"><span><strong>Migration Toolkit for Virtualization</strong></span></a></h2><h4 id="introduction-3" tabindex="-1"><a class="header-anchor" href="#introduction-3"><span>Introduction</span></a></h4><p>The Migration Toolkit for Virtualization (MTV) enables you to migrate virtual machines from VMware vSphere, Red Hat Virtualization, or OpenStack to OpenShift Virtualization running on Red Hat OpenShift Virtualization platform.</p><p><img src="`+G+'" alt=""><strong>FIGURE 61.</strong> Migration Toolkit for Virtualization supported providers</p><p>MTV simplifies the migration process, allowing you to seamlessly move VM workloads to OpenShift Virtualization</p><p>MTV supports Cold migration which is the default migration type. The source virtual machines are shutdown while the data is copied. Cold migration from</p><ul><li><p>VMware vSphere</p></li><li><p>Red Hat Virtualization (RHV)</p></li><li><p>OpenStack</p></li><li><p>Remote OpenShift Virtualization clusters</p></li></ul><p>MTV supports warm migration from VMware vSphere and from RHV. In warm migration most of the data is copied during the pre-copy stage while the source virtual machines (VMs) are running. Then the VMs are shut down and the remaining data is copied during the cutover stage</p><h4 id="installing-mtv-operator" tabindex="-1"><a class="header-anchor" href="#installing-mtv-operator"><span>Installing MTV Operator</span></a></h4><p>You can install MTV operator using web console and CLI</p><h4 id="installing-mtv-operator-using-web-console" tabindex="-1"><a class="header-anchor" href="#installing-mtv-operator-using-web-console"><span>Installing MTV Operator using web console</span></a></h4><ol><li>In the web console, navigate to Ecosystem -&gt; Software Ctaalog.</li><li>Select an existing project name or create new project.</li><li>Use the Filter by keyword field to search for mtv-operator.</li><li>Click the Migration Toolkit for Virtualization Operator tile and then click Install.</li></ol><p><img src="'+j+'" alt=""><strong>FIGURE 62.</strong> Migration Toolkit Operator deployment</p><ol start="5"><li>After the Migration Toolkit for Virtualization Operator is installed successfully create ForkliftController Instance.</li></ol><p><img src="'+B+`" alt=""><strong>FIGURE 63.</strong> ForliftController Instance creation</p><h4 id="installing-mtv-operator-using-cli" tabindex="-1"><a class="header-anchor" href="#installing-mtv-operator-using-cli"><span>Installing MTV Operator using CLI</span></a></h4><ol><li>Create the openshift-mtv project:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">$ <span class="token function">cat</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF<span class="token bash punctuation"> <span class="token operator">|</span> oc apply <span class="token parameter variable">-f</span> -</span></span>
<span class="line">apiVersion: project.openshift.io/v1</span>
<span class="line">kind: Project</span>
<span class="line">metadata:</span>
<span class="line">  name: openshift-mtv</span>
<span class="line">EOF</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Create an OperatorGroup CR called migration:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">$ <span class="token function">cat</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF<span class="token bash punctuation"> <span class="token operator">|</span> oc apply <span class="token parameter variable">-f</span> -</span></span>
<span class="line">apiVersion: operators.coreos.com/v1</span>
<span class="line">kind: OperatorGroup</span>
<span class="line">metadata:</span>
<span class="line">  name: migration</span>
<span class="line">  namespace: openshift-mtv</span>
<span class="line">spec:</span>
<span class="line">  targetNamespaces:</span>
<span class="line">    - openshift-mtv</span>
<span class="line">EOF</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>Create a Subscription CR for the Operator:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">$ <span class="token function">cat</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF<span class="token bash punctuation"> <span class="token operator">|</span> oc apply <span class="token parameter variable">-f</span> -</span></span>
<span class="line">apiVersion: operators.coreos.com/v1alpha1</span>
<span class="line">kind: Subscription</span>
<span class="line">metadata:</span>
<span class="line">  name: mtv-operator</span>
<span class="line">  namespace: openshift-mtv</span>
<span class="line">spec:</span>
<span class="line">  channel: release-v2.6</span>
<span class="line">  installPlanApproval: Automatic</span>
<span class="line">  name: mtv-operator</span>
<span class="line">  source: redhat-operators</span>
<span class="line">  sourceNamespace: openshift-marketplace</span>
<span class="line">  startingCSV: &quot;mtv-operator.v2.6.1&quot;</span>
<span class="line">EOF</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>Create a ForkliftController CR:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">$ <span class="token function">cat</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF<span class="token bash punctuation"> <span class="token operator">|</span> oc apply <span class="token parameter variable">-f</span> -</span></span>
<span class="line">apiVersion: forklift.konveyor.io/v1beta1</span>
<span class="line">kind: ForkliftController</span>
<span class="line">metadata:</span>
<span class="line">  name: forklift-controller</span>
<span class="line">  namespace: openshift-mtv</span>
<span class="line">spec:</span>
<span class="line">  olm_managed: true</span>
<span class="line">EOF</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="cross-cluster-migration" tabindex="-1"><a class="header-anchor" href="#cross-cluster-migration"><span><strong>Cross-Cluster Migration</strong></span></a></h2><h4 id="introduction-4" tabindex="-1"><a class="header-anchor" href="#introduction-4"><span>Introduction</span></a></h4><p>Cross-cluster migration enables the movement of virtual machines between two OpenShift clusters. This process is a cold migration, where the virtual machine is powered off on the source cluster and recreated on the destination cluster.</p><p>This approach is commonly used for workload redistribution, infrastructure upgrades, and disaster recovery scenarios. The migration is performed using the Migration Toolkit for Virtualization (MTV), which facilitates data transfer and VM recreation across clusters.</p><h4 id="prerequisites-1" tabindex="-1"><a class="header-anchor" href="#prerequisites-1"><span>Prerequisites</span></a></h4><ul><li>OpenShift Virtualization Operator must be installed on both clusters</li><li>Migration Toolkit for Virtualization (MTV) must be installed and configured</li><li>Forklift controller pods must be running</li><li>VM must be in stopped state on source cluster</li></ul><h4 id="configuring-providers-for-cross-cluster-migration" tabindex="-1"><a class="header-anchor" href="#configuring-providers-for-cross-cluster-migration"><span>Configuring Providers for Cross-Cluster Migration</span></a></h4><p>To enable migration, the target cluster must be able to communicate with the source cluster.</p><h4 id="preparing-source-cluster-cluster-a" tabindex="-1"><a class="header-anchor" href="#preparing-source-cluster-cluster-a"><span>Preparing Source Cluster (Cluster A)</span></a></h4><ol><li>Create ServiceAccount for MTV:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc create sa mtv <span class="token parameter variable">-n</span> openshift-mtv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>Grant required permissions:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc adm policy add-cluster-role-to-user cluster-admin <span class="token parameter variable">-z</span> mtv <span class="token parameter variable">-n</span> openshift-mtv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="3"><li>Create token secret:</li></ol><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml" data-title="yml"><pre><code><span class="line"><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1</span>
<span class="line"><span class="token key atrule">kind</span><span class="token punctuation">:</span> Secret</span>
<span class="line"><span class="token key atrule">metadata</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">name</span><span class="token punctuation">:</span> mtv<span class="token punctuation">-</span>token</span>
<span class="line">  <span class="token key atrule">namespace</span><span class="token punctuation">:</span> openshift<span class="token punctuation">-</span>mtv</span>
<span class="line">  <span class="token key atrule">annotations</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">kubernetes.io/service-account.name</span><span class="token punctuation">:</span> mtv</span>
<span class="line"><span class="token key atrule">type</span><span class="token punctuation">:</span> kubernetes.io/service<span class="token punctuation">-</span>account<span class="token punctuation">-</span>token</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>Apply:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc apply <span class="token parameter variable">-f</span> mtv-token.yaml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="5"><li>Extract token:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc get secret mtv-token <span class="token parameter variable">-n</span> openshift-mtv <span class="token parameter variable">-o</span> <span class="token assign-left variable">jsonpath</span><span class="token operator">=</span><span class="token string">&#39;{.data.token}&#39;</span> <span class="token operator">|</span> base64 <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="creating-provider-on-target-cluster-clsuter-b" tabindex="-1"><a class="header-anchor" href="#creating-provider-on-target-cluster-clsuter-b"><span>Creating Provider on Target Cluster (Clsuter B)</span></a></h4><ol><li><p>Navigate to Virtualization → Migration → Providers.</p></li><li><p>Click Create Provider.</p></li><li><p>Provide the following details:</p><ul><li>Type: OpenShift Virtualization</li><li>Name: sno1 (change as per requirement)</li><li>URL: Source cluster API (e.g. https://&lt;api-ip&gt;:6443)</li><li>Token: Token generated from Cluster A</li><li>Enable: Skip certificate validation</li></ul></li></ol><p><img src="`+H+'" alt=""><strong>FIGURE 64.</strong> Creating Provider for Source Cluster</p><ol start="4"><li>Click Create.</li></ol><h4 id="verifying-provider-status" tabindex="-1"><a class="header-anchor" href="#verifying-provider-status"><span>Verifying Provider Status</span></a></h4><ol><li><p>On Target Cluster, navigate to Virtualization → Migration → Providers.</p></li><li><p>You should see:</p></li></ol><p><img src="'+Y+'" alt=""><strong>FIGURE 65.</strong> Provider Status on Target Cluster</p><h4 id="creating-migration-plan" tabindex="-1"><a class="header-anchor" href="#creating-migration-plan"><span>Creating Migration Plan</span></a></h4><ol><li><p>Navigate to Virtualization → Migration → Plans.</p></li><li><p>Click Create Plan.</p></li><li><p>Enter the Plan Name.</p></li><li><p>Select the Provider (cluster-a).</p></li><li><p>Select the Virtual Machine(s) to be migrated.</p></li><li><p>Click Next.</p></li><li><p>Select the Target Provider and Project (namespace).</p></li><li><p>Configure Network Mapping.</p></li><li><p>Configure Storage Mapping.</p></li></ol><p><img src="'+K+'" alt=""><img src="'+J+'" alt=""><strong>FIGURE 66.</strong> Creating a Migration Plan</p><ol start="10"><li>Review the configuration and finalize the plan.</li></ol><h4 id="starting-migration" tabindex="-1"><a class="header-anchor" href="#starting-migration"><span>Starting Migration</span></a></h4><ol><li><p>Click Start Migration.</p><p>During migration:</p><ul><li>Exporter pod is created on Cluster A</li><li>Importer pod is created on Cluster B</li><li>VM disks are transferred over network</li><li>New PVC and VM are created on Cluster B</li></ul></li></ol><p><img src="'+W+'" alt=""><img src="'+Q+`" alt=""><strong>FIGURE 67.</strong> Execution of Migration Plan</p><h4 id="monitoring-migration" tabindex="-1"><a class="header-anchor" href="#monitoring-migration"><span>Monitoring Migration</span></a></h4><ol><li>Check MTV pods:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc get pods <span class="token parameter variable">-n</span> openshift-mtv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>Check target namespace:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc get pods <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span>target-namespace<span class="token operator">&gt;</span></span>
<span class="line">oc get pvc <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span>target-namespace<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>PVC status progression: Pending → Bound</p><h4 id="validation-1" tabindex="-1"><a class="header-anchor" href="#validation-1"><span>Validation</span></a></h4><ol><li>Verify VM on target cluster:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc get vm <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span>namespace<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li>Start the virtual machine:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc start vm <span class="token operator">&lt;</span>vm-name<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="3"><li>Verify VM instance:</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">oc get vmi <span class="token parameter variable">-n</span> <span class="token operator">&lt;</span>namespace<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="4"><li>Access VM console and validate workload.</li></ol>`,303)]))}const ae=n(Z,[["render",X],["__file","Virtualization.html.vue"]]),ne=JSON.parse('{"path":"/Virtualization/Virtualization.html","title":"OpenShift Virtualization","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"Install and Configure Openshift Virtulization","slug":"install-and-configure-openshift-virtulization","link":"#install-and-configure-openshift-virtulization","children":[]},{"level":2,"title":"Deploying Virtual Machines on UserDefinedNetworks (UDN)","slug":"deploying-virtual-machines-on-userdefinednetworks-udn","link":"#deploying-virtual-machines-on-userdefinednetworks-udn","children":[]},{"level":2,"title":"HotPlugging","slug":"hotplugging","link":"#hotplugging","children":[]},{"level":2,"title":"Live migration","slug":"live-migration","link":"#live-migration","children":[]},{"level":2,"title":"Migration Toolkit for Virtualization","slug":"migration-toolkit-for-virtualization","link":"#migration-toolkit-for-virtualization","children":[]},{"level":2,"title":"Cross-Cluster Migration","slug":"cross-cluster-migration","link":"#cross-cluster-migration","children":[]}],"git":{},"filePathRelative":"Virtualization/Virtualization.md"}');export{ae as comp,ne as data};
